import React, { useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { MapPin, Navigation, Phone, Search, Signal, Truck } from 'lucide-react';
import { useAdmin } from '../lib/store';
import { Avatar, Badge, MapView, OrderStatusBadge, PageHeader, cn } from '../lib/ui';
import { formatUZS } from '../lib/mock';

export const Tracking = () => {
  const { t } = useTranslation();
  const { couriers, orders, notify } = useAdmin();
  const [query, setQuery] = useState('');
  const [selectedCourier, setSelectedCourier] = useState<string | null>(null);
  const [selectedOrder, setSelectedOrder] = useState<string | null>(null);

  const activeOrders = orders.filter((o) => ['confirmed', 'preparing', 'delivering'].includes(o.status));
  const onlineCouriers = couriers.filter((c) => c.status !== 'offline');

  const filteredCouriers = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return onlineCouriers;
    return onlineCouriers.filter((c) => `${c.name} ${c.phone}`.toLowerCase().includes(q));
  }, [onlineCouriers, query]);

  const currentOrder = activeOrders.find((o) => o.id === selectedOrder) ?? activeOrders[0];
  const highlighted = selectedCourier ? [couriers.find((c) => c.id === selectedCourier)!] : couriers;

  return (
    <div className="animate-fade-up">
      <PageHeader
        title={t('trackingTitle')}
        subtitle={t('trackingSubtitle')}
        action={
          <span className="badge bg-brand-500/15 text-brand-700 dark:text-brand-300">
            <span className="h-1.5 w-1.5 animate-pulse rounded-full bg-brand-500" /> {t('live')} · Demo
          </span>
        }
      />

      <div className="grid grid-cols-1 gap-5 xl:grid-cols-[1fr_360px]">
        <div className="card overflow-hidden p-3 sm:p-4">
          <div className="mb-3 flex flex-col gap-2 sm:flex-row sm:items-center">
            <div className="relative flex-1">
              <Search size={17} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-[var(--muted)]" />
              <input className="input pl-10" placeholder={t('searchCourier')} value={query} onChange={(e) => setQuery(e.target.value)} />
            </div>
            <div className="flex items-center gap-2">
              <Badge tone="success"><Signal size={11} /> {onlineCouriers.length} {t('couriersOnline')}</Badge>
              <Badge tone="info">{activeOrders.length} faol buyurtma</Badge>
            </div>
          </div>
          <MapView couriers={highlighted.filter(Boolean)} order={currentOrder} height={520} />
          <div className="mt-3 grid grid-cols-2 gap-2 sm:grid-cols-4">
            {[
              { label: 'Onlayn kuryer', value: String(onlineCouriers.length), tone: 'text-brand-600 dark:text-brand-400' },
              { label: 'Faol buyurtma', value: String(activeOrders.length), tone: 'text-sky-600 dark:text-sky-400' },
              { label: "O'rtacha ETA", value: '28 daq', tone: 'text-amber-600 dark:text-amber-400' },
              { label: "O'rtacha masofa", value: '4.2 km', tone: 'text-violet-600 dark:text-violet-400' },
            ].map((s) => (
              <div key={s.label} className="card-soft p-2.5">
                <p className="text-[9px] font-bold uppercase tracking-wider text-[var(--muted)]">{s.label}</p>
                <p className={cn('mt-0.5 font-display text-lg font-extrabold', s.tone)}>{s.value}</p>
              </div>
            ))}
          </div>
        </div>

        <div className="space-y-4">
          <div className="card p-4">
            <div className="mb-3 flex items-center justify-between">
              <h2 className="font-display text-base font-extrabold">{t('couriers')}</h2>
              <span className="text-[10px] font-bold text-[var(--muted)]">{filteredCouriers.length} ta</span>
            </div>
            <div className="max-h-[300px] space-y-2 overflow-y-auto pr-1">
              {filteredCouriers.map((c) => {
                const order = activeOrders.find((o) => o.courierId === c.id);
                return (
                  <button
                    key={c.id}
                    onClick={() => { setSelectedCourier(selectedCourier === c.id ? null : c.id); if (order) setSelectedOrder(order.id); }}
                    className={cn(
                      'w-full rounded-xl border p-2.5 text-left transition hover:bg-[var(--surface-2)]',
                      selectedCourier === c.id && 'border-brand-500 bg-brand-500/5',
                    )}
                    style={{ borderColor: selectedCourier === c.id ? undefined : 'var(--border)' }}
                  >
                    <div className="flex items-center gap-2.5">
                      <Avatar emoji={c.emoji} size="sm" online />
                      <div className="min-w-0 flex-1">
                        <p className="truncate text-[11px] font-extrabold">{c.name}</p>
                        <p className="text-[10px] text-[var(--muted)]">{c.vehicle} · ⭐ {c.rating}</p>
                      </div>
                      <Badge tone={c.status === 'busy' ? 'warning' : 'success'}>{c.status === 'busy' ? t('busy') : t('online')}</Badge>
                    </div>
                    {order && (
                      <div className="mt-2 flex items-center justify-between rounded-lg bg-[var(--surface-3)] px-2 py-1 text-[10px] font-bold">
                        <span>#{order.id}</span>
                        <span className="text-brand-600 dark:text-brand-400">{order.eta}</span>
                      </div>
                    )}
                  </button>
                );
              })}
              {filteredCouriers.length === 0 && <p className="rounded-xl bg-[var(--surface-2)] p-4 text-center text-xs text-[var(--muted)]">{t('noCouriers')}</p>}
            </div>
          </div>

          <div className="card p-4">
            <div className="mb-3 flex items-center justify-between">
              <h2 className="font-display text-base font-extrabold">Faol buyurtmalar</h2>
              <span className="text-[10px] font-bold text-[var(--muted)]">{activeOrders.length} ta</span>
            </div>
            <div className="max-h-[300px] space-y-2 overflow-y-auto pr-1">
              {activeOrders.map((o) => {
                const c = couriers.find((x) => x.id === o.courierId);
                return (
                  <button
                    key={o.id}
                    onClick={() => { setSelectedOrder(o.id); if (o.courierId) setSelectedCourier(o.courierId); }}
                    className={cn(
                      'w-full rounded-xl border p-2.5 text-left transition hover:bg-[var(--surface-2)]',
                      selectedOrder === o.id && 'border-brand-500 bg-brand-500/5',
                    )}
                    style={{ borderColor: selectedOrder === o.id ? undefined : 'var(--border)' }}
                  >
                    <div className="flex items-center justify-between gap-2">
                      <p className="text-[11px] font-extrabold">#{o.id}</p>
                      <OrderStatusBadge status={o.status} />
                    </div>
                    <p className="mt-1 flex items-center gap-1 truncate text-[10px] text-[var(--muted)]"><MapPin size={10} /> {o.address}</p>
                    <div className="mt-1.5 flex items-center justify-between text-[10px] font-bold">
                      <span className="flex items-center gap-1">{c ? `${c.emoji} ${c.name.split(' ')[0]}` : t('unassigned')}</span>
                      <span>{formatUZS(o.total)}</span>
                    </div>
                  </button>
                );
              })}
              {activeOrders.length === 0 && <p className="rounded-xl bg-[var(--surface-2)] p-4 text-center text-xs text-[var(--muted)]">Faol buyurtma yo'q</p>}
            </div>
          </div>

          {currentOrder && (
            <div className="card p-4">
              <h2 className="font-display text-base font-extrabold">Buyurtma #{currentOrder.id}</h2>
              <div className="mt-3 space-y-2 text-xs">
                <div className="flex items-center gap-2"><MapPin size={13} className="text-brand-500" /><span className="flex-1 text-[var(--muted)]">{currentOrder.address}</span></div>
                <div className="flex items-center gap-2"><Truck size={13} className="text-brand-500" /><span className="flex-1 text-[var(--muted)]">{t('eta')}: <b className="text-[var(--text)]">{currentOrder.eta}</b></span></div>
                <div className="flex items-center gap-2"><Navigation size={13} className="text-brand-500" /><span className="flex-1 text-[var(--muted)]">{t('distance')}: <b className="text-[var(--text)]">3.8 km</b></span></div>
              </div>
              <div className="mt-3 flex gap-1.5">
                <a href={`tel:${currentOrder.phone.replace(/\s/g, '')}`} className="btn-secondary btn-sm flex-1"><Phone size={12} /> {t('call')}</a>
                <button className="btn-primary btn-sm flex-1" onClick={() => notify('Yo\'nalish demo rejimda ochildi', 'info')}><Navigation size={12} /> {t('navigate')}</button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};
